from typing import List

class Solution:
    def restoreOrder(self, times: List[int], participants: List[str]) -> List[str]:
        # Pair times and participants, then sort by completion time ascending
        pairs = sorted(zip(times, participants), key=lambda x: x[0])
        return [p for _, p in pairs]

#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    std::vector<std::string> restoreOrder(std::vector<int>& times, std::vector<std::string>& participants) {
        int n = times.size();
        std::vector<std::pair<int, std::string>> pairs;
        pairs.reserve(n);
        for (int i = 0; i < n; ++i) {
            pairs.push_back({times[i], participants[i]});
        }
        std::sort(pairs.begin(), pairs.end(), [](const auto& a, const auto& b) {
            return a.first < b.first;
        });
        std::vector<std::string> res;
        res.reserve(n);
        for (const auto& p : pairs) {
            res.push_back(p.second);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String[] restoreOrder(int[] times, String[] participants) {
        int n = times.length;
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) indices[i] = i;

        Arrays.sort(indices, Comparator.comparingInt(i -> times[i]));
        String[] res = new String[n];
        for (int i = 0; i < n; i++) {
            res[i] = participants[indices[i]];
        }
        return res;
    }
}

var restoreOrder = function(times, participants) {
    const indices = Array.from({ length: times.length }, (_, i) => i);
    indices.sort((a, b) => times[a] - times[b]);
    return indices.map(i => participants[i]);
};
